insert into public.reminders (id, kind, arabic, english, source_ref, video_url, verified_by, published, sort) values
  ('quran-33-56', 'quran', 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'Indeed, Allah and His angels send blessings upon the Prophet. O you who have believed, send blessings upon him and greet him with peace.', 'Sūrat al-Aḥzāb 33:56', null, null, true, 0),
  ('muslim-408', 'hadith', 'مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا', 'Whoever sends blessings upon me once, Allah sends blessings upon him ten times.', 'Ṣaḥīḥ Muslim 408', null, null, true, 1),
  ('abudawud-1047', 'hadith', 'إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ ... فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ، فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ', 'Among the best of your days is Friday … so send abundant blessings upon me on it, for your blessings are presented to me.', 'Sunan Abī Dāwūd 1047', null, null, true, 2),
  ('tirmidhi-484', 'hadith', 'أَوْلَى النَّاسِ بِي يَوْمَ الْقِيَامَةِ أَكْثَرُهُمْ عَلَيَّ صَلَاةً', 'The closest of people to me on the Day of Resurrection are those who sent the most blessings upon me.', 'Jāmiʿ at-Tirmidhī 484', null, null, true, 3),
  ('video-1', 'video', 'اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبِيِّنَا مُحَمَّدٍ', 'A short video reminder will play here once videos are hosted.', 'Video slot', null, null, true, 4),
  ('quran-21-107', 'quran', 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ', 'And We have not sent you except as a mercy to the worlds.', 'Sūrat al-Anbiyāʾ 21:107', null, null, true, 5),
  ('nasai-1297', 'hadith', 'مَنْ صَلَّى عَلَيَّ صَلَاةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرَ صَلَوَاتٍ، وَحُطَّتْ عَنْهُ عَشْرُ خَطِيئَاتٍ، وَرُفِعَتْ لَهُ عَشْرُ دَرَجَاتٍ', 'Whoever sends one blessing upon me, Allah sends ten blessings upon him, ten sins are removed from him, and he is raised ten degrees.', 'Sunan an-Nasāʾī 1297', null, null, true, 6),
  ('quran-68-4', 'quran', 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', 'And indeed, you are of a great moral character.', 'Sūrat al-Qalam 68:4', null, null, true, 7),
  ('abudawud-2042', 'hadith', 'وَصَلُّوا عَلَيَّ، فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُ كُنْتُمْ', 'And send blessings upon me, for your blessings reach me wherever you are.', 'Sunan Abī Dāwūd 2042', null, null, true, 8),
  ('quran-33-21', 'quran', 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ', 'There has certainly been for you in the Messenger of Allah an excellent example.', 'Sūrat al-Aḥzāb 33:21', null, null, true, 9),
  ('bukhari-3370', 'hadith', 'اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ', 'O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrāhīm and upon the family of Ibrāhīm. Truly, You are Praiseworthy, Glorious.', 'Ṣaḥīḥ al-Bukhārī 3370', null, null, true, 10),
  ('quran-9-128', 'quran', 'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', 'There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; he is anxious over you, and to the believers he is kind and merciful.', 'Sūrat at-Tawbah 9:128', null, null, true, 11),
  ('tirmidhi-2457', 'hadith', 'إِذًا تُكْفَى هَمَّكَ، وَيُغْفَرُ لَكَ ذَنْبُكَ', 'When a Companion said he would devote all his prayer to sending blessings on him, he ﷺ replied: “Then your worries will be taken care of, and your sins will be forgiven.”', 'Jāmiʿ at-Tirmidhī 2457', null, null, true, 12),
  ('quran-3-31', 'quran', 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ', 'Say: If you love Allah, then follow me; Allah will love you and forgive you your sins.', 'Sūrat Āl ʿImrān 3:31', null, null, true, 13)
